package com.aicharacter.v3; import org.json.JSONException;import org.json.JSONObject;
public final class DeveloperReport{public long timestamp;public String category,severity,system,observation,cause,context,action;public DeveloperReport(long t,String c,String sev,String sys,String obs,String cause,String ctx,String act){timestamp=t;category=c;severity=sev;system=sys;observation=obs;this.cause=cause;context=ctx;action=act;}public JSONObject toJson()throws JSONException{JSONObject j=new JSONObject();j.put("timestamp",timestamp);j.put("category",category);j.put("severity",severity);j.put("system",system);j.put("observation",observation);j.put("cause",cause);j.put("context",context);j.put("action",action);return j;}public static DeveloperReport fromJson(JSONObject j){return new DeveloperReport(j.optLong("timestamp"),j.optString("category"),j.optString("severity"),j.optString("system"),j.optString("observation"),j.optString("cause"),j.optString("context"),j.optString("action"));}}
